void emitMethod(SootMethod method) {
  if (ca.mcgill.sable.soot.Main.isProfilingOptimization)   ca.mcgill.sable.soot.Main.buildJasminTimer.end();
  Body activeBody=method.getActiveBody();
  if (!(activeBody instanceof BafBody))   throw new RuntimeException("method: " + method.getName() + " has an invalid active body!");
  BafBody body=(BafBody)activeBody;
  if (body == null)   throw new RuntimeException("method: " + method.getName() + " has no active body!");
  if (ca.mcgill.sable.soot.Main.isProfilingOptimization)   ca.mcgill.sable.soot.Main.buildJasminTimer.start();
  List instList=body.getUnitList();
  int stackLimitIndex=-1;
  emit(".method " + Modifier.toString(method.getModifiers()) + " "+ method.getName()+ jasminDescriptorOf(method));
  subroutineToReturnAddressSlot=new HashMap(10,0.7f);
  {
    Iterator boxIt=body.getUnitBoxes().iterator();
    instToLabel=new HashMap(instList.size() * 2 + 1,0.7f);
    labelCount=0;
    while (boxIt.hasNext()) {
      {
        InstBox box=(InstBox)boxIt.next();
        if (!instToLabel.containsKey(box.getUnit()))         instToLabel.put(box.getUnit(),"label" + labelCount++);
      }
    }
  }
  {
    Iterator trapIt=body.getTraps().iterator();
    while (trapIt.hasNext()) {
      Trap trap=(Trap)trapIt.next();
      if (trap.getBeginUnit() != trap.getEndUnit())       emit(".catch " + slashify(trap.getException().getName()) + " from "+ instToLabel.get(trap.getBeginUnit())+ " to "+ instToLabel.get(trap.getEndUnit())+ " using "+ instToLabel.get(trap.getHandlerUnit()));
    }
  }
  {
    int localCount=0;
    int[] paramSlots=new int[method.getParameterCount()];
    int thisSlot=0;
    Set assignedLocals=new HashSet();
    Map groupColorPairToSlot=new HashMap(body.getLocalCount() * 2 + 1,0.7f);
    localToSlot=new HashMap(body.getLocalCount() * 2 + 1,0.7f);
    {
      List paramTypes=method.getParameterTypes();
      if (!method.isStatic()) {
        thisSlot=0;
        localCount++;
      }
      for (int i=0; i < paramTypes.size(); i++) {
        paramSlots[i]=localCount;
        localCount+=sizeOfType((Type)paramTypes.get(i));
      }
    }
    {
      Iterator instIt=instList.iterator();
      while (instIt.hasNext()) {
        Inst s=(Inst)instIt.next();
        if (s instanceof IdentityInst && ((IdentityInst)s).getLeftOp() instanceof Local) {
          Local l=(Local)((IdentityInst)s).getLeftOp();
          IdentityRef identity=(IdentityRef)((IdentityInst)s).getRightOp();
          int slot=0;
          if (identity instanceof ThisRef) {
            if (method.isStatic())             throw new RuntimeException("Attempting to use 'this' in static method");
            slot=thisSlot;
          } else if (identity instanceof ParameterRef)           slot=paramSlots[((ParameterRef)identity).getIndex()]; else {
            continue;
          }
          localToSlot.put(l,new Integer(slot));
          assignedLocals.add(l);
        }
      }
    }
    {
      Iterator localIt=body.getLocals().iterator();
      while (localIt.hasNext()) {
        Local local=(Local)localIt.next();
        if (!assignedLocals.contains(local)) {
          localToSlot.put(local,new Integer(localCount));
          localCount+=sizeOfType((Type)local.getType());
          assignedLocals.add(local);
        }
      }
      if (!Modifier.isNative(method.getModifiers()) && !Modifier.isAbstract(method.getModifiers())) {
        emit("    .limit stack ?");
        stackLimitIndex=code.size() - 1;
        emit("    .limit locals " + localCount);
      }
    }
  }
  {
    Iterator codeIt=instList.iterator();
    isEmittingMethodCode=true;
    maxStackHeight=0;
    isNextGotoAJsr=false;
    while (codeIt.hasNext()) {
      Inst s=(Inst)codeIt.next();
      if (instToLabel.containsKey(s))       emit(instToLabel.get(s) + ":");
      try {
        emitInst(s);
      } catch (RuntimeException | NotDeclaredException e) {
        // Handle the exception, e.g., log it or rethrow it
        e.printStackTrace();
      }
    }
    isEmittingMethodCode=false;
    if (!Modifier.isNative(method.getModifiers()) && !Modifier.isAbstract(method.getModifiers()))     code.set(stackLimitIndex,"    .limit stack " + maxStackHeight);
  }
  emit(".end method");
}
